    표8_상담적용: [
        {"상황":"같은 문제를 반복적으로 겪는 성도", "성경원리":"실패한 방법을 반복하지 않는 것이 지혜이다. 새로운 접근이 필요하다", "실제적용":"지금까지 시도한 방법을 정리하고, 그 중 효과가 없었던 것을 과감히 버리며, 새로운 접근을 함께 모색합니다"},
        {"상황":"다른 사람의 조언만 따르다 실패한 성도", "성경원리":"남의 말을 그대로 빌려 쓰지 않고, 하나님께 직접 들은 말씀으로 살아야 한다", "실제적용":"개인 묵상과 기도를 통해 하나님의 직접적 인도를 구하는 방법을 안내하고, 자기만의 신앙적 확신을 세우도록 돕습니다"},
        {"상황":"목회 방법론에 한계를 느끼는 교역자", "성경원리":"실패한 방법을 반복하는 대신 하나님의 새로운 역사에 열린 자세가 필요하다", "실제적용":"기존 방법론을 재평가하고, 새로운 목회적 접근을 탐색하며, 다른 교회의 혁신적 사례를 연구하도록 안내합니다"}
    ],
    표9_교차참조: [
        {"구절":"이사야 43:18-19", "연결점":"이전 일을 기억하지 말며 옛적 일을 생각하지 말라 보라 내가 새 일을 행하리니", "구분":"구약"},
        {"구절":"예레미야 33:3", "연결점":"너는 내게 부르짖으라 내가 네게 응답하겠고 네가 알지 못하는 크고 비밀한 일을 네게 보이리라", "구분":"구약"},
        {"구절":"시편 40:3", "연결점":"새 노래 곧 우리 하나님께 올릴 찬송을 내 입에 두셨으니", "구분":"구약"},
        {"구절":"잠언 26:11", "연결점":"개가 그 토한 것을 다시 먹는 것 같이 미련한 자는 그 미련한 것을 거듭 행하느니라", "구분":"구약"},
        {"구절":"고린도후서 5:17", "연결점":"누구든지 그리스도 안에 있으면 새로운 피조물이라 이전 것은 지나갔으니 보라 새 것이 되었도다", "구분":"신약"},
        {"구절":"마가복음 2:22", "연결점":"새 포도주를 낡은 가죽 부대에 넣는 자가 없나니 만일 그렇게 하면 새 포도주가 부대를 터뜨려", "구분":"신약"},
        {"구절":"요한일서 2:27", "연결점":"너희는 주께 받은 바 기름 부음이 너희 안에 거하나니 아무도 너희를 가르칠 필요가 없고", "구분":"신약"},
        {"구절":"로마서 12:2", "연결점":"이 세대를 본받지 말고 오직 마음을 새롭게 함으로 변화를 받아 하나님의 선하시고 기뻐하시고 온전하신 뜻이 무엇인지 분별하도록 하라", "구분":"신약"}
    ]
